// Client side, built into the browser
const events = new EventSource('/prices/stream');
events.onmessage = (event) => {
    updatePrice(JSON.parse(event.data));
};

// Server side: keep writing events into the same open response
res.setHeader('Content-Type', 'text/event-stream');
function sendUpdate(price) {
    res.write(`data: ${JSON.stringify(price)}\n\n`);
}

